const int TRIG = 7;
const int ECHO = 6;
const int BUZZER = 8;
const int LED = 13;

long medirDistancia() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long duracao = pulseIn(ECHO, HIGH);
  return duracao / 58;
}

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  long cm = medirDistancia();
  Serial.print("Distancia: ");
  Serial.print(cm);
  Serial.println(" cm");
  if (cm > 0 && cm < 20) {
    tone(BUZZER, 1000);
    digitalWrite(LED, HIGH);
  } else {
    noTone(BUZZER);
    digitalWrite(LED, LOW);
  }
  delay(100);
}

