const int IN1 = 8, IN2 = 7, ENA = 5;   // motor esquerdo
const int IN3 = 4, IN4 = 2, ENB = 6;   // motor direito
const int TRIG = 10, ECHO = 11;        // ultrassom
const int SENSOR_ESQ = A0, SENSOR_DIR = A1;

const int VELOCIDADE_BASE = 150;
const float KP = 0.15;
const int DISTANCIA_MINIMA = 15;

// velocidade de -255 (ré) a 255 (frente)
void motor(int in1, int in2, int en, int vel) {
  vel = constrain(vel, -255, 255);
  if (vel >= 0) {
    digitalWrite(in1, HIGH);
    digitalWrite(in2, LOW);
  } else {
    digitalWrite(in1, LOW);
    digitalWrite(in2, HIGH);
    vel = -vel;
  }
  analogWrite(en, vel);
}

long distanciaCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long duracao = pulseIn(ECHO, HIGH, 30000);
  if (duracao == 0) return 999;   // nada à frente
  return duracao / 58;
}

void setup() {
  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT); pinMode(ENA, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT); pinMode(ENB, OUTPUT);
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
}

void loop() {
  if (distanciaCm() < DISTANCIA_MINIMA) {
    motor(IN1, IN2, ENA, 0);
    motor(IN3, IN4, ENB, 0);
    return;
  }
  int esquerdo = analogRead(SENSOR_ESQ);
  int direito = analogRead(SENSOR_DIR);
  int erro = esquerdo - direito;        // > 0: a linha está mais para a esquerda
  int correcao = KP * erro;
  motor(IN1, IN2, ENA, VELOCIDADE_BASE - correcao);
  motor(IN3, IN4, ENB, VELOCIDADE_BASE + correcao);
  delay(5);
}
